(()=>{const {t,esc}=F,request=(...args)=>Admin.request(...args);let teams=[],volunteers=[],volPage=1,volPages=1,ticket=0,teamId=null,album=[],sponsors=[],epoch=0,busy=0,stream=null,scanFrame=null,scanEpoch=0;const $=s=>document.querySelector(s),report=(id,message,error=false)=>{const el=$(id);el.textContent=t(message);el.className=error?'error':'success'};
function choices(select){const selected=select.value;select.innerHTML=Admin.events.map(e=>`<option value="${esc(e.id)}">${esc(I18N.event(e).name)}</option>`).join('');if(Admin.events.some(e=>e.id===selected))select.value=selected}
function syncEvents(){['#volunteerEvent','#operationEvent'].forEach(s=>choices($(s)));$('#viewResults').href='race.html?event='+encodeURIComponent($('#operationEvent').value);}
function drawTeams(){ $('#volunteerTeams').innerHTML=teams.map(team=>`<article class="team-card"><span class="eyebrow">${t(F.roles[team.role])}</span><h3>${esc(t(team.name))}</h3><p>${t('المسؤول')}: ${esc(team.leader)||t('لم يُحدد بعد')}</p><p>${t('نقطة العمل')}: ${esc(team.location)}</p><p>${new Date(team.start).toLocaleString(I18N.lang)}<br>${new Date(team.end).toLocaleString(I18N.lang)}</p><div class="team-capacity"><strong>${team.assigned} / ${team.needed}</strong><span>${t('متطوع موزّع')}</span></div><button class="outline-btn" data-edit-team="${esc(team.id)}">${t('تعديل الفريق')}</button></article>`).join('')||'<p>'+t('أنشئ الفرق المقترحة أو أضف فريقك الأول.')+'</p>';$('#defaultTeams').disabled=!!teams.length}
function drawVolunteers(){ $('#volunteerList').innerHTML=volunteers.map(v=>`<article class="volunteer-row"><div><h3>${esc(v.name)}</h3><p><span dir="ltr">${esc(v.email)}</span> · <span dir="ltr">${esc(v.phone)}</span></p><p>${t('المهمة المفضلة')}: ${t(F.roles[v.preferred_role])} · ${t(v.status)}</p><p>${t('مقاس البلوزة')}: ${esc(v.shirt_size||'—')}</p>${v.qualified?`<p>${t('ذكر امتلاك تأهيل إسعاف؛ يلزم التحقق.')}</p>`:''}${v.available_from||v.available_to?`<p>${t('وقت التفرغ')}: ${v.available_from?new Date(v.available_from).toLocaleString(I18N.lang):'—'} / ${v.available_to?new Date(v.available_to).toLocaleString(I18N.lang):'—'}</p>`:''}<p>${esc(v.notes)}</p></div><form data-volunteer="${esc(v.id)}"><label>${t('الفريق')}<select name="teamId"><option value="">${t('بدون فريق')}</option>${teams.map(team=>`<option value="${esc(team.id)}" ${team.id===v.team_id?'selected':''}>${esc(t(team.name))} (${team.assigned}/${team.needed})</option>`).join('')}</select></label><label>${t('الحالة')}<select name="status">${['pending','assigned','attended','declined'].map(s=>`<option value="${s}" ${s===v.status?'selected':''}>${t(s)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="medicalVerified" ${v.medical_verified?'checked':''}>${t('تحققت من تأهيل الإسعاف')}</label><button class="btn small">${t('حفظ التوزيع')}</button></form></article>`).join('')||'<p>'+t('لا توجد طلبات تطوّع مطابقة.')+'</p>';$('#volunteerPage').textContent=t('الصفحة')+' '+volPage+' / '+volPages;$('#volunteerPrevious').disabled=volPage<=1;$('#volunteerNext').disabled=volPage>=volPages}
async function refreshVolunteers(){const current=++ticket,eventId=$('#volunteerEvent').value;if(!eventId)return;try{const q=new URLSearchParams({eventId,page:String(volPage),q:$('#volunteerSearch').value,status:$('#volunteerState').value});const [teamData,volData]=await Promise.all([request('/api/admin/volunteer-teams?eventId='+encodeURIComponent(eventId)),request('/api/admin/volunteers?'+q)]);if(current!==ticket)return;teams=teamData;volunteers=volData.items;volPages=volData.pages;if(volPage>volPages){volPage=volPages;return refreshVolunteers()}drawTeams();drawVolunteers();const summary=Object.fromEntries(volData.summary.map(s=>[s.status,s.total]));$('#volunteerSummary').innerHTML=['pending','assigned','attended','declined'].map(s=>`<article><strong>${summary[s]||0}</strong><span>${t(s)}</span></article>`).join('')}catch(e){Admin.status('#dashboardStatus',e.message,true)}}
$('#volunteerEvent').addEventListener('change',()=>{volPage=1;refreshVolunteers()});$('#volunteerState').addEventListener('change',()=>{volPage=1;refreshVolunteers()});let searchTimer;$('#volunteerSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{volPage=1;refreshVolunteers()},300)});$('#refreshVolunteers').onclick=refreshVolunteers;$('#volunteerPrevious').onclick=()=>{if(volPage>1){volPage--;refreshVolunteers()}};$('#volunteerNext').onclick=()=>{if(volPage<volPages){volPage++;refreshVolunteers()}};
$('#defaultTeams').onclick=async()=>{const button=$('#defaultTeams');button.disabled=true;try{await request('/api/admin/volunteer-teams/defaults',{method:'POST',body:JSON.stringify({eventId:$('#volunteerEvent').value})});await refreshVolunteers()}catch(e){Admin.status('#dashboardStatus',e.message,true);button.disabled=false}};
function localDate(date){const d=new Date(date);return new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}function openTeam(team=null){teamId=team?.id||null;const form=$('#teamForm'),event=Admin.events.find(e=>e.id===$('#volunteerEvent').value);if(!event)return;form.reset();$('#teamRole').innerHTML=Object.entries(F.roles).map(([role,label])=>`<option value="${role}">${t(label)}</option>`).join('');form.elements.location.value=event.location;form.elements.start.value=localDate(new Date(event.start)-90*60000);form.elements.end.value=localDate(+new Date(event.start)+5*3600000);if(team){for(const key of ['name','role','leader','location','needed'])form.elements[key].value=team[key];form.elements.start.value=localDate(team.start);form.elements.end.value=localDate(team.end)}report('#teamStatus','');$('#teamDialog').showModal()}
$('#newTeam').onclick=()=>openTeam();$('#volunteerTeams').onclick=e=>{const button=e.target.closest('[data-edit-team]');if(button)openTeam(teams.find(t=>t.id===button.dataset.editTeam))};$('#teamDialog .close').onclick=()=>$('#teamDialog').close();$('#teamForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.eventId=$('#volunteerEvent').value;b.start=new Date(b.start).toISOString();b.end=new Date(b.end).toISOString();const button=e.target.querySelector('[type=submit],button:not([type])');button.disabled=true;try{await request('/api/admin/volunteer-teams'+(teamId?'/'+teamId:''),{method:teamId?'PUT':'POST',body:JSON.stringify(b)});$('#teamDialog').close();await refreshVolunteers()}catch(err){report('#teamStatus',err.message,true)}finally{button.disabled=false}};
$('#volunteerList').onsubmit=async e=>{const form=e.target.closest('[data-volunteer]');if(!form)return;e.preventDefault();const f=new FormData(form),button=form.querySelector('button');button.disabled=true;try{await request('/api/admin/volunteers/'+form.dataset.volunteer,{method:'PUT',body:JSON.stringify({teamId:f.get('teamId'),status:f.get('status'),medicalVerified:f.has('medicalVerified')})});await refreshVolunteers();Admin.status('#dashboardStatus','تم تحديث مهمة المتطوّع.')}catch(err){Admin.status('#dashboardStatus',err.message,true)}finally{button.disabled=false}};
async function download(route,filename){try{const r=await fetch(F.api+route,{credentials:'same-origin',headers:{'Accept-Language':I18N.lang}});if(!r.ok){const d=await r.json();throw Error(t(d.error))}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){Admin.status('#dashboardStatus',e.message,true)}}$('#exportParticipants').onclick=()=>download('/api/admin/export/participants'+($('#participantRace').value?'?eventId='+encodeURIComponent($('#participantRace').value):''),'Run_Msafat_participants.xlsx');$('#exportVolunteers').onclick=()=>download('/api/admin/export/volunteers?eventId='+encodeURIComponent($('#volunteerEvent').value),'Run_Msafat_volunteers.xlsx');
$('#participantsBody').addEventListener('click',async e=>{const b=e.target.closest('[data-cancel-registration]');if(!b||!confirm(t('هل تؤكد إلغاء المشاركة؟')))return;try{await request('/api/admin/registrations/'+b.dataset.cancelRegistration+'/cancel',{method:'POST',body:'{}'});await Admin.refresh()}catch(err){Admin.status('#dashboardStatus',err.message,true)}});
async function checkin(code){const d=await request('/api/admin/checkin',{method:'POST',body:JSON.stringify({eventId:$('#operationEvent').value,code})});report('#checkinStatus',t(d.message)+' '+d.name+' #'+d.bib);return d}$('#checkinForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await checkin(e.target.elements.code.value);e.target.reset()}catch(err){report('#checkinStatus',err.message,true)}finally{button.disabled=false}};
function stopScanner(){scanEpoch++;if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#scannerVideo').srcObject=null;$('#scannerVideo').hidden=true;$('#stopScanner').hidden=true;$('#startScanner').disabled=false}
$('#stopScanner').onclick=stopScanner;$('#operationEvent').onchange=()=>{stopScanner();$('#viewResults').href='race.html?event='+encodeURIComponent($('#operationEvent').value)};
$('#startScanner').onclick=async()=>{stopScanner();const current=scanEpoch;$('#startScanner').disabled=true;try{if(!navigator.mediaDevices?.getUserMedia)throw Error(t('الكاميرا تحتاج HTTPS أو localhost. أدخل الرقم يدويًا.'));const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});if(current!==scanEpoch){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;const video=$('#scannerVideo'),canvas=$('#scannerCanvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});video.srcObject=stream;video.hidden=false;$('#stopScanner').hidden=false;await video.play();function scan(){if(current!==scanEpoch)return;if(video.readyState>=2){canvas.width=Math.min(video.videoWidth,800);canvas.height=Math.round(video.videoHeight*canvas.width/video.videoWidth);ctx.drawImage(video,0,0,canvas.width,canvas.height);const found=jsQR(ctx.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height);if(found?.data?.startsWith('MSAFAT:')){const code=found.data;stopScanner();checkin(code).catch(e=>report('#checkinStatus',e.message,true));return}}scanFrame=requestAnimationFrame(scan)}scan()}catch(e){stopScanner();report('#checkinStatus',e.message||'تعذّر فتح الكاميرا. أدخل الرقم يدويًا.',true)}};
$('#resultForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),parts=f.get('time').split(':').map(Number),seconds=parts[0]*3600+parts[1]*60+parts[2],button=e.target.querySelector('button');button.disabled=true;try{const d=await request('/api/admin/results',{method:'POST',body:JSON.stringify({eventId:$('#operationEvent').value,bib:Number(f.get('bib')),seconds})});report('#resultStatus',d.message)}catch(err){report('#resultStatus',err.message,true)}finally{button.disabled=false}};
async function refreshStats(){try{const data=await request('/api/admin/statistics');function chart(id,rows,label){const max=Math.max(1,...rows.map(r=>r.total));$(id).innerHTML=rows.length?rows.map(r=>`<div class="stat-bar"><div><span>${esc(label(r))}</span><b>${r.total}</b></div><i style="width:${r.total/max*100}%"></i></div>`).join(''):'<p>'+t('لا توجد بيانات بعد.')+'</p>'}chart('#dailyStats',data.daily,r=>r.day);chart('#distanceStats',data.distances,r=>I18N.distance(r.distance));chart('#stateStats',data.states,r=>t(r.state));chart('#volunteerStats',data.volunteers,r=>t(r.status))}catch(e){Admin.status('#dashboardStatus',e.message,true)}}$('#refreshStats').onclick=refreshStats;['volunteers','operations','statistics'].forEach(key=>$('#'+key+'Tab').onclick=()=>Admin.selectTab(key));
function capacities(values={}){const input=$('#eventForm').elements.distances,distances=input.value.split(/[,،]/).map(s=>s.trim()).filter(Boolean);const old=Object.fromEntries([...document.querySelectorAll('[data-capacity]')].map(el=>[el.dataset.capacity,el.value]));$('#capacityInputs').innerHTML=distances.map(d=>`<label>${esc(I18N.distance(d))}<input data-capacity="${esc(d)}" type="number" min="1" max="100000" value="${esc(values[d]??old[d]??'')}" placeholder="${t('بدون حد')}"></label>`).join('')}
$('#eventForm').elements.distances.addEventListener('input',()=>capacities());
function drawAlbum(){$('#albumPreviews').innerHTML=album.map(i=>`<figure><img src="${esc(F.image(i.url))}" alt="${t('ألبوم السباق')}"><div><button type="button" data-remove-album="${esc(i.id)}">${t('إزالة')}</button></div></figure>`).join('')}
function drawSponsors(){$('#sponsorInputs').innerHTML=sponsors.map((s,i)=>`<fieldset class="sponsor-editor" data-sponsor="${i}"><legend>${t('راعٍ')} ${i+1}</legend><div class="form-grid"><label>${t('اسم الراعي')}<input data-field="name" required maxlength="100" value="${esc(s.name)}"></label><label>${t('موقع الراعي')}<input data-field="website" type="url" placeholder="https://example.com" value="${esc(s.website)}" dir="ltr"></label><label>${t('شعار الراعي')}<input type="file" data-sponsor-logo="${i}" accept="image/jpeg,image/png,image/webp"></label>${s.image?`<img class="sponsor-preview" src="${esc(F.image(s.image.url))}" alt="${esc(s.name)}">`:''}</div><button type="button" data-remove-sponsor="${i}" class="outline-btn">${t('إزالة')}</button></fieldset>`).join('')}
function readSponsors(){document.querySelectorAll('[data-sponsor]').forEach(row=>{const s=sponsors[Number(row.dataset.sponsor)];if(s)row.querySelectorAll('[data-field]').forEach(input=>s[input.dataset.field]=input.value)});return sponsors}
$('#addSponsor').onclick=()=>{readSponsors();if(sponsors.length<20){sponsors.push({name:'',website:'',imageId:'',image:null});drawSponsors()}};$('#sponsorInputs').onclick=e=>{const b=e.target.closest('[data-remove-sponsor]');if(b&&!busy){readSponsors();sponsors.splice(Number(b.dataset.removeSponsor),1);drawSponsors()}};
async function upload(file){if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error(t('اختر صور JPG أو PNG أو WebP أصغر من 5 ميغابايت.'));return request('/api/admin/uploads',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file})}
$('#sponsorInputs').onchange=async e=>{const input=e.target.closest('[data-sponsor-logo]');if(!input?.files.length)return;const current=epoch,index=Number(input.dataset.sponsorLogo),file=input.files[0];input.value='';busy++;$('#saveEvent').disabled=true;try{const image=await upload(file);if(current===epoch){readSponsors();sponsors[index].imageId=image.id;sponsors[index].image=image;drawSponsors()}}catch(err){report('#albumStatus',err.message,true)}finally{busy--;$('#saveEvent').disabled=!!busy}};
$('#albumUpload').onchange=async e=>{const files=[...e.target.files],current=epoch;e.target.value='';if(album.length+files.length>40)return report('#albumStatus','الألبوم يقبل 40 صورة كحد أقصى.',true);busy++;$('#saveEvent').disabled=true;report('#albumStatus','جارٍ رفع الصور…');try{for(const file of files){const image=await upload(file);if(current!==epoch)return;album.push(image);drawAlbum()}report('#albumStatus','تم رفع الصور. احفظ السباق لنشرها.')}catch(err){report('#albumStatus',err.message,true)}finally{busy--;$('#saveEvent').disabled=!!busy}};
$('#albumPreviews').onclick=e=>{const b=e.target.closest('[data-remove-album]');if(b&&!busy){album=album.filter(i=>i.id!==b.dataset.removeAlbum);drawAlbum()}};
function openEvent(e){epoch++;album=[...(e?.album||[])];sponsors=(e?.sponsors||[]).map(s=>({...s}));$('#capacityInputs').innerHTML='';setTimeout(()=>capacities(e?.capacities||{}),0);const form=$('#eventForm');form.elements.feeILS.value=(e?.feeMinor||0)/100;form.elements.waitlistEnabled.checked=!!e?.waitlistEnabled;form.elements.routeText.value=(e?.route||[]).map(p=>[p.kind,p.lat,p.lng,p.label].join(',')).join('\n');drawAlbum();drawSponsors();report('#albumStatus','')}
function eventPayload(){const form=$('#eventForm');return {feeMinor:Math.round(Number(form.elements.feeILS.value)*100),waitlistEnabled:form.elements.waitlistEnabled.checked,capacities:Object.fromEntries([...document.querySelectorAll('[data-capacity]')].filter(el=>el.value).map(el=>[el.dataset.capacity,Number(el.value)])),route:form.elements.routeText.value.split('\n').filter(s=>s.trim()).map(line=>{const [kind,lat,lng,...label]=line.split(',').map(s=>s.trim());return {kind,lat,lng,label:label.join(',')}}),sponsors:readSponsors().map(s=>({name:s.name,website:s.website,imageId:s.imageId})),albumIds:album.map(i=>i.id)}}
window.AdminFeatures={syncEvents,refreshVolunteers,refreshStats,stopScanner,openEvent,eventPayload,get busy(){return busy>0},reset(){ticket++;epoch++;stopScanner();teams=[];volunteers=[];$('#volunteerList').innerHTML='';$('#volunteerTeams').innerHTML='';if($('#teamDialog').open)$('#teamDialog').close()}};window.addEventListener('languagechange',()=>{syncEvents();if(!$('#volunteersPanel').hidden)refreshVolunteers();if(!$('#statisticsPanel').hidden)refreshStats();readSponsors();drawSponsors();drawAlbum();capacities()});window.addEventListener('pagehide',stopScanner);
})();
